sp_widget.script:
(function() { data.trends = { by_month: [], by_status: [] };
  try { var statusCounts = {}; var gr = new GlideRecord("x_1433041_identi_0_application"); gr.addQuery("active", true); gr.setLimit(200); gr.query();
    while (gr.next()) { var s = gr.getDisplayValue("questionnaire_status"); statusCounts[s] = (statusCounts[s] || 0) + 1; }
    for (var k in statusCounts) data.trends.by_status.push({ label: k, count: statusCounts[k] });
  } catch (e) { gs.error("IBAR Trend Analysis widget error: " + e.message); }
})();
